const input = $json || {};
const required = ['restaurantId', 'messageId', 'from', 'text'];
const missing = required.filter((key) => !String(input[key] ?? '').trim());
if (missing.length) {
  throw new Error(`CHATBOT_INPUT_MISSING:${missing.join(',')}`);
}
const phone = String(input.from).replace(/[^0-9]/g, '');
if (phone.length < 7 || phone.length > 15) {
  throw new Error('CHATBOT_PHONE_INVALID');
}
return [{
  json: {
    restaurantId: String(input.restaurantId).trim(),
    messageId: String(input.messageId).trim().slice(0, 190),
    from: phone,
    name: String(input.name ?? '').trim().slice(0, 120),
    text: String(input.text).trim().slice(0, 2000),
    mode: input.mode === 'test' ? 'test' : 'live'
  }
}];

const envelope = $json || {};
const statusCode = Number(envelope.statusCode ?? 200);
const body = envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;
if (body?.duplicate === true || body?.suppressDelivery === true) {
  return [{ json: { route: 'ignore', reason: body.duplicate ? 'duplicate' : 'test', backend: body } }];
}
if (statusCode === 409 && body?.error === 'CHATBOT_BUSY') {
  return [{ json: { route: 'retry', retryAfterMs: Number(body.retryAfterMs || 1500), backend: body } }];
}
if (statusCode < 200 || statusCode >= 300 || body?.ok !== true) {
  return [{ json: { route: 'error', statusCode, error: String(body?.error || 'CHATBOT_BACKEND_FAILED') } }];
}
if (body.handoff === true) {
  return [{ json: { route: 'handoff', reply: String(body.reply || ''), action: body.action || null } }];
}
return [{ json: { route: 'reply', reply: String(body.reply || ''), action: body.action || null } }];
